import * as fs from 'node:fs/promises';
import * as path from 'node:path';
import {
  recoveryRecordSchema,
  type ConversationRecord,
  type RecoveryRecord,
  type RecoveryResume,
} from '@kai/contracts';

const MAX_PROMPT_CHARS = 4_000;
const MAX_ACTIVITY_CHARS = 300;

function fileFor(directory: string, conversationId: string): string {
  // Conversation ids are generated by KAI; still refuse anything that is not a plain file name.
  if (!/^[\w.-]+$/.test(conversationId)) throw new Error('Invalid conversation id.');
  return path.join(directory, `${conversationId}.json`);
}

/**
 * One small file per active run. The file is written when a run starts, refreshed at every
 * event, and removed when the run ends, so any file present at startup is an interrupted run.
 */
export class RecoveryStore {
  constructor(private readonly directory: string) {}

  async begin(record: Omit<RecoveryRecord, 'schemaVersion' | 'prompt' | 'lastActivity'> & { prompt: string }): Promise<void> {
    await this.write({
      ...record,
      schemaVersion: 1,
      prompt: record.prompt.slice(0, MAX_PROMPT_CHARS),
      lastActivity: 'Run started',
    });
  }

  async touch(conversationId: string, lastActivity: string, now: Date = new Date()): Promise<void> {
    const current = await this.read(conversationId);
    if (!current) return;
    await this.write({
      ...current,
      updatedAt: now.toISOString(),
      eventCount: current.eventCount + 1,
      lastActivity: lastActivity.slice(0, MAX_ACTIVITY_CHARS),
    });
  }

  async end(conversationId: string): Promise<void> {
    await fs.rm(fileFor(this.directory, conversationId), { force: true });
  }

  async read(conversationId: string): Promise<RecoveryRecord | null> {
    try {
      return recoveryRecordSchema.parse(JSON.parse(await fs.readFile(fileFor(this.directory, conversationId), 'utf8')));
    } catch {
      return null;
    }
  }

  /** Newest first. Unreadable or corrupt files are skipped, never fatal at startup. */
  async list(): Promise<RecoveryRecord[]> {
    let names: string[];
    try {
      names = await fs.readdir(this.directory);
    } catch {
      return [];
    }
    const records = await Promise.all(
      names.filter((name) => name.endsWith('.json')).map((name) => this.read(path.basename(name, '.json'))),
    );
    return records
      .filter((record): record is RecoveryRecord => record !== null)
      .sort((left, right) => right.updatedAt.localeCompare(left.updatedAt));
  }

  private async write(record: RecoveryRecord): Promise<void> {
    await fs.mkdir(this.directory, { recursive: true });
    const target = fileFor(this.directory, record.conversationId);
    const temporary = `${target}.tmp`;
    await fs.writeFile(temporary, JSON.stringify(recoveryRecordSchema.parse(record)), 'utf8');
    await fs.rename(temporary, target);
  }
}

export function describeEvent(event: ConversationRecord['events'][number]): string | null {
  switch (event.type) {
    case 'tool.call':
      return `Tool ${event.name} ${event.status}`;
    case 'file.change':
      return `File ${event.action}: ${event.path}`;
    case 'approval.request':
      return `Waiting for approval: ${event.title}`;
    case 'agent.lifecycle':
      return event.detail || `Agent ${event.status}`;
    default:
      return null;
  }
}

/** Local recap built only from what KAI stored, so it works with every service stopped. */
export function buildRecap(record: RecoveryRecord, changedFiles: readonly string[]): string {
  const lines = [
    `Interrupted run: ${record.title || record.conversationId}`,
    `Agent: ${record.agent} (${record.execution === 'api' ? `API, ${record.route}` : 'CLI'}), autonomy ${record.autonomy}.`,
    `Started ${record.startedAt}; last activity ${record.updatedAt} after ${record.eventCount} events.`,
    `Last activity: ${record.lastActivity}`,
    record.goal ? `Goal: ${record.goal}` : null,
    `Original request:\n${record.prompt}`,
  ];
  if (changedFiles.length > 0) lines.push(`Files changed so far: ${changedFiles.slice(0, 20).join(', ')}.`);
  if (record.checkpoint) {
    lines.push(`A Git checkpoint (${record.checkpoint.ref.slice(0, 12)}) was taken before the run, so file changes can be reviewed or restored.`);
  } else {
    lines.push('No Git checkpoint exists for this run, so file changes cannot be restored automatically.');
  }
  return lines.filter((line): line is string => line !== null).join('\n');
}

export function buildResume(record: RecoveryRecord): RecoveryResume {
  const prompt = [
    'The previous run of this task was interrupted before it finished (the app closed or crashed).',
    `Original request:\n${record.prompt}`,
    `Last recorded activity: ${record.lastActivity}`,
    'Some files may already be edited. Check the current state of the project first, do not repeat work that is already done, then continue the task and finish it.',
  ].join('\n\n');
  return {
    conversationId: record.conversationId,
    prompt,
    agent: record.agent,
    execution: record.execution,
    route: record.route,
    autonomy: record.autonomy,
  };
}
